import java.util.*;
import java.io.*;

public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        String s = sc.next();
        int end = (int)Math.pow(10, s.length());
        int res = 0;
        for (int i = 0; i < end; i += 25) {
            if (match(s, i)) {
                res++;
            }
        }
        pw.println(res);
        pw.close();
    }

    public static boolean match(String s, int n) {
        StringBuilder sb = new StringBuilder(String.valueOf(n));
        while (sb.length() < s.length()) {
            sb.insert(0, '0');
        }
        String numStr = sb.toString();
        for (int i = 0; i < s.length(); i++) {
            char patternChar = s.charAt(i);
            char numChar = numStr.charAt(s.length() - 1 - i);
            if (patternChar == 'X') {
                continue;
            } else if (patternChar != '_') {
                if (patternChar != numChar) {
                    return false;
                }
            }
        }
        return true;
    }
}
